content:
560       * initialized concurrently. */
   561      if(serviceType == UA_SERVICETYPE_NORMAL)
   562          service(server, session, request, response);
   563
   564      /* Start the message */
   565      UA_NodeId typeId = UA_NODEID_NUMERIC(0, responseType->binaryEncodingId);
   566      UA_MessageContext mc;
   567      retval = UA_MessageContext_begin(&mc, channel, requestId, UA_MESSAGETYPE_MSG);
   568      if(retval != UA_STATUSCODE_GOOD)
   569          goto cleanup;
   570
   571      /* Assert's required for clang-analyzer */
   572      UA_assert(mc.buf_pos == &mc.messageBuffer.data[UA_SECURE_MESSAGE_HEADER_LENGTH]);
   573      UA_assert(mc.buf_end <= &mc.messageBuffer.data[mc.messageBuffer.length]);
   574
   575      retval = UA_MessageContext_encode(&mc, &typeId, &UA_TYPES[UA_TYPES_NODEID]);
   576      if(retval != UA_STATUSCODE_GOOD)
   577          goto cleanup;
   578
   579      switch(serviceType) {
   580      case UA_SERVICETYPE_CUSTOM:
   581          /* Was processed before...*/
   582          retval = UA_MessageContext_encode(&mc, response, responseType);
   583          break;
   584      case UA_SERVICETYPE_INSITU:
   585          retval = serviceInsitu
   586              (server, session, &mc, request, (UA_ResponseHeader*)response);
   587          break;
   588      case UA_SERVICETYPE_NORMAL:
   589      default:
   590          retval = UA_MessageContext_encode(&mc, response, responseType);
   591          break;
   592      }
   593
   594      /* Finish sending the message */
   595      if(retval != UA_STATUSCODE_GOOD) {
   596          UA_MessageContext_abort(&mc);
   597          goto cleanup;
   598      }
   599
   600      retval = UA_MessageContext_finish(&mc);
   601
   602   cleanup:
   603      if(retval != UA_STATUSCODE_GOOD)
   604          UA_LOG_INFO_CHANNEL(server->config.logger, channel,
   605                              "Could not send the message over the SecureChannel "
   606                              "with StatusCode %s", UA_StatusCode_name(retval));
   607      /* Clean up */
   608      UA_deleteMembers(request, requestType);
   609      UA_deleteMembers(response, responseType);
   610      return retval;
   611  }
