   614  static void
   615  processSecureChannelMessage(void *application, UA_SecureChannel *channel,
   616                              UA_MessageType messagetype, UA_UInt32 requestId,
   617                              const UA_ByteString *message) {
   618      UA_Server *server = (UA_Server*)application;
   619      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   620      switch(messagetype) {
   621      case UA_MESSAGETYPE_OPN:
   622          UA_LOG_TRACE_CHANNEL(server->config.logger, channel,
   623                               "Process an OPN on an open channel");
   624          retval = processOPN(server, channel, requestId, message);
   625          break;
   626      case UA_MESSAGETYPE_MSG:
   627          UA_LOG_TRACE_CHANNEL(server->config.logger, channel, "Process a MSG");
   628          retval = processMSG(server, channel, requestId, message);
   629          break;
   630      case UA_MESSAGETYPE_CLO:
   631          UA_LOG_TRACE_CHANNEL(server->config.logger, channel, "Process a CLO");
   632          Service_CloseSecureChannel(server, channel);
   633          break;
