   635          UA_LOG_TRACE_CHANNEL(server->config.logger, channel, "Invalid message type");
   636          retval = UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
   637          break;
   638      }
   639      if(retval != UA_STATUSCODE_GOOD) {
   640          UA_LOG_INFO_CHANNEL(server->config.logger, channel,
   641                              "Processing the message failed with StatusCode %s."
   642                              "Closing the channel", UA_StatusCode_name(retval));
