   139  UA_StatusCode
   140  UA_SecureChannelManager_open(UA_SecureChannelManager *cm, UA_SecureChannel *channel,
   141                               const UA_OpenSecureChannelRequest *request,
   142                               UA_OpenSecureChannelResponse *response) {
   143      if(channel->state != UA_SECURECHANNELSTATE_FRESH) {
   144          UA_LOG_ERROR_CHANNEL(cm->server->config.logger, channel,
   145                               "Called open on already open or closed channel");
   146          return UA_STATUSCODE_BADINTERNALERROR;
   147      }
   148
   149      if(request->securityMode != UA_MESSAGESECURITYMODE_NONE &&
   150         UA_ByteString_equal(&channel->securityPolicy->policyUri, &UA_SECURITY_POLICY_NONE_URI)) {
   151          return UA_STATUSCODE_BADSECURITYMODEREJECTED;
   152      }
   153
   154      channel->securityMode = request->securityMode;
   155      channel->securityToken.createdAt = UA_DateTime_nowMonotonic();
   156      channel->securityToken.channelId = cm->lastChannelId++;
   157      channel->securityToken.createdAt = UA_DateTime_now();
   158
   159      /* Set the lifetime. Lifetime 0 -> set the maximum possible */
   160      channel->securityToken.revisedLifetime =
   161          (request->requestedLifetime > cm->server->config.maxSecurityTokenLifetime) ?
   162          cm->server->config.maxSecurityTokenLifetime : request->requestedLifetime;
   163      if(channel->securityToken.revisedLifetime == 0)
   164          channel->securityToken.revisedLifetime = cm->server->config.maxSecurityTokenLifetime;
   165
   166      /* Set the nonces and generate the keys */
   167      UA_StatusCode retval = UA_ByteString_copy(&request->clientNonce, &channel->remoteNonce);
   168      if(retval != UA_STATUSCODE_GOOD)
   169          return retval;
   170
   171      retval = UA_SecureChannel_generateLocalNonce(channel);
   172      if(retval != UA_STATUSCODE_GOOD)
   173          return retval;
   174
   175      retval = UA_SecureChannel_generateNewKeys(channel);
   176      if(retval != UA_STATUSCODE_GOOD)
   177          return retval;
   178
   179      /* Set the response */
   180      retval = UA_ByteString_copy(&channel->localNonce, &response->serverNonce);
   181      if(retval != UA_STATUSCODE_GOOD)
   182          return retval;
   183
   184      retval = UA_ChannelSecurityToken_copy(&channel->securityToken, &response->securityToken);
   185      if(retval != UA_STATUSCODE_GOOD)
   186          return retval;
   187
   188      response->responseHeader.timestamp = UA_DateTime_now();
   189      response->responseHeader.requestHandle = request->requestHeader.requestHandle;
   190
   191      /* The channel is open */
   192      channel->state = UA_SECURECHANNELSTATE_OPEN;
   193
   194      return UA_STATUSCODE_GOOD;
   195  }
